// TH15 v1.00b Stage 2 道中 th15_s2_w08
// 源：st02.ecl.txt MainSub05 1076-1094（GirlD01 前后各一对 + Phantom01R 三轮各 9 对）
const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

// 源 etSprite type7；TH15 合成映射复用现代弹型槽
const TH15_RING_BALL2: int = 464;

// GirlD01_at (st02:507-553)：60 帧后开始，A 次齐射，间隔逐档。
// etAim mode9 = A + (-1)^q*(R_i + H(M,q))；速度按成对层 k=(q&~1) 取值。
// 源同帧发满 10*M 颗；目标单任务预算不足，拆成两个同帧子任务各发一半层，弹集合同帧不变。
async sub girl_d01_at(part: int) {
    var rank: int = global(GVAR_RANK);
    var layers: int = 2;
    var s0: fx = 1.6fx;
    var s1: fx = 1.6fx;
    var volleys: int = 2;
    var gap: int = 120;
    if rank == RANK_NORMAL {
        layers = 6;
        volleys = 3;
    }
    if rank == RANK_HARD {
        layers = 8;
        s0 = 2.5fx;
        volleys = 4;
        gap = 90;
    }
    if rank == RANK_LUNATIC {
        layers = 8;
        s0 = 2.9fx;
        volleys = 6;
        gap = 60;
    }
    wait(60);
    for v in 0..volleys {
        var aim: int = aim_player() as int;
        var ex: fx = $self_x;
        var ey: fx = $self_y;
        for q in 0..layers {
            if q % 2 == part {
                var k: int = q - q % 2;
                var speed: fx = s0;
                if layers > 1 {
                    speed = s0 + (s1 - s0) * k / (layers - 1);
                }
                var retreat: fx = 4fx * speed;
                // delta=3deg(546 BAM)，偶数层 M 的 H(k)=(k/2+0.5)*delta
                var h: int = 273 + 546 * (q / 2);
                var sign: int = 1;
                if q % 2 != 0 {
                    sign = -1;
                }
                for i in 0..10 {
                    var a: int = aim + sign * ((i * 65536) / 10 + h);
                    var ang: angle = a as angle;
                    // 源 EX type2 ANIM a=1：出生位移 position -= 4*velocity
                    var px: fx = ex - retreat * cos(ang);
                    var py: fx = ey - retreat * sin(ang);
                    _ = fire(TH15_RING_BALL2, 4, px, py, speed, ang, none, none);
                }
            }
        }
        wait(gap);
    }
}

// GirlD01 (st02:482-505)：90deg 下移，80 帧 3->0，再 120 帧 0->0.6。
async sub girl_d01() {
    set_invuln(65535);
    set_hurtbox(16fx);
    set_hitbox(12fx);
    move_vel(0, 90deg, 3fx, EASE_LINEAR);
    move_vel(80, 90deg, 0fx, EASE_QUAD_IN);
    spawn girl_d01_at(0);
    spawn girl_d01_at(1);
    wait(80);
    move_speed(120, 0.6fx, EASE_QUAD_IN);
    wait(60);
    loop { wait(1000); }
}

// Phantom01_at (st02:1214-1234)：etAim mode0、1 路；层数与层速逐档，A 次随机间隔齐射。
async sub phantom01_at() {
    var rank: int = global(GVAR_RANK);
    var layers: int = 1;
    var s0: fx = 1fx;
    var s1: fx = 1fx;
    var volleys: int = 1;
    if rank == RANK_NORMAL {
        layers = 2;
        s0 = 2fx;
        s1 = 0.8fx;
    }
    if rank == RANK_HARD {
        layers = 4;
        s0 = 3fx;
        s1 = 1fx;
        volleys = 2;
    }
    if rank == RANK_LUNATIC {
        layers = 8;
        s0 = 4fx;
        s1 = 1fx;
        volleys = 3;
    }
    for v in 0..volleys {
        wait(20 + rand(200));
        var aim: int = aim_player() as int;
        var ex: fx = $self_x;
        var ey: fx = $self_y;
        for q in 0..layers {
            var speed: fx = s0;
            if layers > 1 {
                speed = s0 + (s1 - s0) * q / (layers - 1);
            }
            var ang: angle = aim as angle;
            var retreat: fx = 4fx * speed;
            var px: fx = ex - retreat * cos(ang);
            var py: fx = ey - retreat * sin(ang);
            _ = fire(TH15_RING_BALL2, 2, px, py, speed, ang, none, none);
        }
    }
}

// Phantom01 (st02:1176-1194)：moveVel(90deg,0.5)、120 帧 0.5->1.0；
// moveEllipseRel(F0=0, 2deg/f, r10, d0, beta=ABS_ANGLE=90deg, s=0) 只产生 ±10px 水平正弦偏移；
// 无 DPS 外壳不执行死亡回调，flagSet(12) 的屏外保留无等价写口。
async sub phantom01(sx: fx) {
    set_invuln(65535);
    set_hurtbox(14fx);
    set_hitbox(8fx);
    var theta: int = 0;
    var base_y: fx = -24fx;
    var n: int = 0;
    move_to(0, sx + 10fx, -24fx, EASE_LINEAR);
    spawn phantom01_at();
    loop {
        n = n + 1;
        var speed: fx = 1fx;
        if n <= 120 {
            var u: fx = (n as fx) / 120fx;
            speed = 0.5fx + 0.5fx * u * u * u * u;
        }
        theta = theta + 364;
        var nx: fx = sx + 10fx * cos(theta as angle);
        var ny: fx = base_y + speed;
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
        base_y = ny;
        wait(1);
    }
}

// 局部帧 0 = 源 1076：先 GirlD01 对，再三轮 9 对 Phantom01R（30 帧一对），
// 810 帧后补最后一对 GirlD01。
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(-32fx, -24fx, 1000, 0, 0, 0, girl_d01);
    _ = spawn_enemy(32fx, -24fx, 1000, 0, 0, 0, girl_d01);
    for round in 0..3 {
        for e in 0..9 {
            var x: fx = 16fx * ((e + 1) as fx);
            _ = spawn_enemy(x, -24fx, 100, 0, 0, 0, phantom01(x));
            _ = spawn_enemy(-x, -24fx, 100, 0, 0, 0, phantom01(-x));
            wait(30);
        }
    }
    _ = spawn_enemy(-32fx, -24fx, 1000, 0, 0, 0, girl_d01);
    _ = spawn_enemy(32fx, -24fx, 1000, 0, 0, 0, girl_d01);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
